import java.io.*;import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.tags.*;class assetsInspect{public static void main(String[]a)throws Exception{var s=new SWF(new FileInputStream(a[0]),false);for(var c:s.getCharacters(false).values())if(c instanceof DefineSpriteTag d)for(var f:d.getTimeline().getFrames())for(var l:f.layers.values())if(l.instanceName!=null&&(l.instanceName.contains("helmet")||l.instanceName.contains("foot")||l.instanceName.contains("drill")||l.instanceName.contains("face")))System.out.println(d.spriteId+" frame "+f.frame+" name "+l.instanceName+" child "+l.characterId);}}
